# Debug flag set by the dialog based on Settings → Enable debug logging.
# Kept module-level so helper parsers (_parseSlangBrowsePage, _httpGet, ...) can emit consistent traces.
_DEBUG_ENABLED = False

def _setDebugEnabled(flag: bool) -> None:
    global _DEBUG_ENABLED
    try:
        _DEBUG_ENABLED = bool(flag)
    except Exception:
        _DEBUG_ENABLED = False

def _dbg(msg: str) -> None:
    # Use log.warning so it is visible in NVDA log even when log level is not set to debug.
    if not _DEBUG_ENABLED:
        return
    try:
        log.warning("mwLookup DEBUG " + (msg or ""))
    except Exception:
        pass


