# Shared cookie jar/opener to reduce 403 blocks on paged listings (e.g. /slang/page-2).
_COOKIE_JAR = http.cookiejar.CookieJar()
_URL_OPENER = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(_COOKIE_JAR))


def _resetMwSession(reason: str = "") -> None:
    """Discard the current MW HTTP session and start with a fresh cookie jar.

    Cloudflare challenges often appear after the user's network changes (for
    example enabling/disabling a VPN). Reusing cookies from the old route can
    make the next request look suspicious. When a challenge is detected, reset
    the in-memory cookie jar/opener before the retry path warms up the site.
    """
    global _COOKIE_JAR, _URL_OPENER
    try:
        if reason:
            _dbg(f"resetting MW HTTP session: {reason}")
        else:
            _dbg("resetting MW HTTP session")
    except Exception:
        pass
    _COOKIE_JAR = http.cookiejar.CookieJar()
    _URL_OPENER = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(_COOKIE_JAR))


def _browserLikeHeaders(url: str, referer: Optional[str] = None, binary: bool = False) -> Dict[str, str]:
    """Return conservative browser-like headers for MW requests.

    This does not try to solve or bypass Cloudflare challenges. It only makes
    the add-on's normal HTTP requests less like a bare Python client, while the
    Cloudflare detector/retry path remains the safety net.
    """
    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/125.0.0.0 Safari/537.36"
        ),
        "Accept-Language": "en-US,en;q=0.9",
        "Accept-Encoding": "gzip, deflate",
        "Connection": "keep-alive",
        "DNT": "1",
    }
    if binary:
        headers.update({
            "Accept": "audio/mpeg,audio/*;q=0.9,*/*;q=0.8",
            "Referer": referer or "https://www.merriam-webster.com/",
        })
        return headers
    headers.update({
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
        "Upgrade-Insecure-Requests": "1",
        "Sec-Fetch-Dest": "document",
        "Sec-Fetch-Mode": "navigate",
        "Sec-Fetch-Site": "same-origin" if referer else "none",
        "Sec-Fetch-User": "?1",
    })
    if referer:
        headers["Referer"] = referer
    return headers


def _retryDelay(attempt: int) -> float:
    """Exponential-style backoff with mild jitter."""
    schedule = (1.0, 2.5, 5.0, 8.0, 12.0)
    try:
        base = schedule[min(attempt, len(schedule)-1)]
    except Exception:
        base = 2.0 * (attempt + 1)
    try:
        return base + random.uniform(0.2, 0.9)
    except Exception:
        return base

def _warmupMwSession() -> None:
    """Lightweight homepage fetch to refresh cookies before retrying."""
    try:
        req = urllib.request.Request("https://www.merriam-webster.com/", headers=_browserLikeHeaders("https://www.merriam-webster.com/"))
        with _URL_OPENER.open(req, timeout=15) as resp:
            resp.read(4096)
    except Exception:
        pass


