def _mergeSettings(stored: Dict[str, Any]) -> Dict[str, Any]:
    """Merge stored settings with defaults and perform light migrations."""
    s = dict(SETTINGS_DEFAULTS)
    try:
        if isinstance(stored, dict):
            s.update(stored)
    except Exception:
        pass
    # Backward compat migrations.
    try:
        # Older builds only had cacheEnabled/debugEnabled.
        if "audioCacheEnabled" not in s:
            s["audioCacheEnabled"] = True
        # Older builds may have stored display toggles; they are no longer supported.
        for _k in ("displayTextPronunciations", "displayAudioPronunciations"):
            try:
                s.pop(_k, None)
            except Exception:
                pass
        if "historyLimit" not in s:
            s["historyLimit"] = int(HISTORY_LIMIT)
        # Ensure types/ranges.
        try:
            hl = int(s.get("historyLimit", HISTORY_LIMIT))
            if hl < 0:
                hl = 0
            if hl > 300:
                hl = 300
            s["historyLimit"] = hl
        except Exception:
            s["historyLimit"] = int(HISTORY_LIMIT)
        for k in (
            "cacheEnabled",
            "audioCacheEnabled",
            "debugEnabled",
            "aggressiveBoilerplateRemoval",
            "keepFavoritesOpen",
        ):
            s[k] = bool(s.get(k, SETTINGS_DEFAULTS.get(k, False)))
        # UI option removed; keep behavior consistent.
        s["aggressiveBoilerplateRemoval"] = True
        # Default lookup mode normalization.
        try:
            m = str(s.get("defaultLookupMode", "dictionary") or "dictionary").strip().lower()
            if m not in ("dictionary", "thesaurus", "slang"):
                m = "dictionary"
            s["defaultLookupMode"] = m
        except Exception:
            s["defaultLookupMode"] = "dictionary"
    except Exception:
        pass
    return s


