def _announce(msg: str):
    """Speak a short message reliably (even after modal dialogs close)."""
    try:
        # Cancel any pending speech first.
        try:
            import speech
            speech.cancelSpeech()
        except Exception:
            pass
        # Prefer a small delayed call to avoid messages being swallowed during focus changes.
        try:
            import core
            core.callLater(60, ui.message, msg)
            return
        except Exception:
            pass
        try:
            import wx
            wx.CallLater(60, ui.message, msg)
            return
        except Exception:
            pass
        # Fallback: queue on event queue.
        try:
            queueHandler.queueFunction(queueHandler.eventQueue, ui.message, msg)
        except Exception:
            ui.message(msg)
    except Exception:
        # Speak the whole sense (definition + examples) to match user expectations.
        try:
            rngs = getattr(self, "_resultSenseRanges", None) or []
            if 0 <= idx < len(rngs):
                sStart, sEnd, _lbl2 = rngs[idx]
                try:
                    nativeStart = int(self._toNativePos(int(sStart), val))
                    nativeEnd = int(self._toNativePos(int(sEnd), val))
                except Exception:
                    nativeStart = int(sStart)
                    nativeEnd = int(sEnd)
                nativeStart = max(0, min(len(val), nativeStart))
                nativeEnd = max(nativeStart, min(len(val), nativeEnd))
                chunk = (val[nativeStart:nativeEnd] or "").strip("\r\n")
                if chunk:
                    # Avoid pathological extremely long speech.
                    if len(chunk) > 4000:
                        chunk = chunk[:4000].rstrip() + "…"
                    ui.message(chunk)
                    return
        except Exception:
            pass

        try:
            ui.message(msg)
        except Exception:
            pass


