        btns.Add(self.prevBtn, 0, wx.RIGHT, 6)
        btns.Add(self.nextBtn, 0, wx.RIGHT, 6)
        btns.Add(self.openBtn, 0, wx.RIGHT, 6)
        btns.AddStretchSpacer(1)
        btns.Add(self.closeBtn, 0)
        main.Add(btns, 0, wx.EXPAND | wx.LEFT | wx.RIGHT | wx.BOTTOM, 8)

        self.SetSizer(main)
        self.SetMinSize((520, 420))

        self._prevUrl = ""
        self._nextUrl = ""
        self.prevBtn.Enable(False)
        self.nextBtn.Enable(False)

        self.list.Bind(wx.EVT_LISTBOX_DCLICK, self.onActivate)
        self.openBtn.Bind(wx.EVT_BUTTON, self.onActivate)
        self.backBtn.Bind(wx.EVT_BUTTON, self.onBack)
        self.prevBtn.Bind(wx.EVT_BUTTON, self.onPrevPage)
        self.nextBtn.Bind(wx.EVT_BUTTON, self.onNextPage)
        self.closeBtn.Bind(wx.EVT_BUTTON, lambda e: self.Close())
