    def onKeyDown(self, evt):
        key = evt.GetKeyCode()
        if key in (wx.WXK_RETURN, wx.WXK_NUMPAD_ENTER):
            self.onActivate(evt)
            return
        if key == wx.WXK_ESCAPE:
            self.Close()
            return
        evt.Skip()

    def onCharHook(self, evt):
        """Catch Enter/Escape reliably (some ListBox builds don't deliver EVT_KEY_DOWN consistently)."""
