    def _pushAndLoad(self, url: str, title: str):
        """Push a new page onto the stack."""
        try:
            curSel = int(self.list.GetSelection())
        except Exception:
            curSel = 0
        try:
            if self._stack:
                u0, t0, _ = self._stack[-1]
                self._stack[-1] = (u0, t0, curSel)
        except Exception:
            pass

        self._stack.append((url, title, 0))
        self._load(url, title, restoreIndex=0)

    def _load(self, url: str, title: str, restoreIndex: int = None):
        self.backBtn.Enable(len(self._stack) > 1)
