        # Dialog-scoped accelerator IDs (layout-independent key handling).
        self._ID_MW_ALT_E = wx.NewIdRef()
        self._ID_MW_ALT_T = wx.NewIdRef()
        self._ID_MW_ALT_D = wx.NewIdRef()
        self._ID_MW_ALT_H = wx.NewIdRef()
