    def _getHistoryLabel(self) -> str:
        try:
            hl = int(self._settings.get("historyLimit", HISTORY_LIMIT))
        except Exception:
            hl = int(HISTORY_LIMIT)
        m = (self._mode or "dictionary").strip().lower()
        labelMode = "Thesaurus" if m == "thesaurus" else "Dictionary"
        if hl <= 0:
            return f"History ({labelMode}, disabled)"
        return f"History ({labelMode}, up to {hl})"

    def _updateHistoryLabel(self) -> None:
        try:
            if hasattr(self, "_historyStaticBox") and self._historyStaticBox:
                self._historyStaticBox.SetLabel(self._getHistoryLabel())
        except Exception:
            pass

    
    def _getResultsLabel(self) -> str:
        m = (self._lastResultsMode or self._mode or "dictionary").strip().lower()
        if m == "thesaurus":
            labelMode = "Thesaurus"
        elif m == "wordplay":
            labelMode = "Wordplay"
        elif m in ("wotd", "wordoftheday", "word_of_the_day"):
            labelMode = "Word of the Day"
        elif m == "slang":
            labelMode = "Slang"
        elif m == "dictionary":
            # Some queries entered in Dictionary mode resolve to the Medical Dictionary.
            # We can label this reliably based on the final page URL (after redirects).
            try:
                if bool(getattr(self, "_currentIsMedical", False)):
                    labelMode = "Medical Dictionary"
                else:
                    labelMode = "Dictionary"
            except Exception:
                labelMode = "Dictionary"
        else:
            # Default/fallback.
            labelMode = "Dictionary"
        return f"Results ({labelMode})"

    def _getSearchLabel(self) -> str:
        m = (self._mode or "dictionary").strip().lower()
        return "Search thesaurus:" if m == "thesaurus" else "Search dictionary:"

    def _updateSearchLabel(self) -> None:
        try:
            if hasattr(self, "_searchLabel") and self._searchLabel:
                self._searchLabel.SetLabel(self._getSearchLabel())
                try:
                    self.Layout()
                except Exception:
                    pass
        except Exception:
            pass

    def _updateResultsLabel(self) -> None:
        """Update the Results group label.

        Per UX: only show "Results (Dictionary/Thesaurus)" when an actual
        Dictionary/Thesaurus entry result is displayed. For Word of the Day,
        Browse pages, suggestions, and the empty state, show no label.
        """
        try:
            if not (hasattr(self, "_resultsStaticBox") and self._resultsStaticBox):
                return
            kind = str(getattr(self, "_resultsKind", "empty") or "empty").strip().lower()
            if kind == "entry":
                self._resultsStaticBox.SetLabel(self._getResultsLabel())
            else:
                # Empty label suppresses NVDA announcing an irrelevant Results group.
                self._resultsStaticBox.SetLabel("")
        except Exception:
            pass

    def _getModeFromUi(self) -> str:
        try:
            if hasattr(self, "modeRadio") and self.modeRadio:
                sel = int(self.modeRadio.GetSelection())
                m = "thesaurus" if sel == 1 else "dictionary"
                return m
        except Exception:
            pass
        return str(getattr(self, "_mode", "dictionary") or "dictionary")

    def _applyMode(self, mode: str) -> None:
        m = (mode or "dictionary").strip().lower()
        if m not in ("dictionary", "thesaurus", "slang"):
            m = "dictionary"
        self._mode = m
        # Update mode-dependent UI pieces.
        self._updateSearchLabel()
        # Update active history view.
        try:
            self._history = list(self._historyThes if m == "thesaurus" else self._historyDict)
            self.history.Set(self._history)
        except Exception:
            pass
        self._updateHistoryLabel()

    def _onModeChanged(self, evt):
        try:
            self._applyMode(self._getModeFromUi())
        except Exception:
            pass
        # Do NOT persist the radio selection automatically.
        # Settings → Default lookup mode controls the mode on next launch.
        return
    def _applyHistoryUi(self) -> None:
        """Update History label, enabled state, and enforce the current limit."""
        try:
            hl = int(self._settings.get("historyLimit", HISTORY_LIMIT))
        except Exception:
            hl = int(HISTORY_LIMIT)
        try:
            if hl <= 0:
                # Disable history feature.
                self._historyDict = []
                self._historyThes = []
                self._history = []
                try:
                    self.history.Set([])
                except Exception:
                    pass
                try:
                    self.history.Disable()
                except Exception:
                    pass
            else:
                # Enforce limit and show the active list.
                self._historyDict = list(self._historyDict or [])[:hl]
                self._historyThes = list(self._historyThes or [])[:hl]
                self._history = list(self._historyThes if self._mode == "thesaurus" else self._historyDict)
                try:
                    self.history.Set(self._history)
                except Exception:
                    pass
                try:
                    self.history.Enable(True)
                except Exception:
                    pass
            # Persist both histories.
            try:
                _saveJson(_historyPathForMode("dictionary"), self._historyDict)
                _saveJson(_historyPathForMode("thesaurus"), self._historyThes)
            except Exception:
                pass
        except Exception:
            pass
        # Update label.
        self._updateHistoryLabel()
        try:
            self.Layout()
        except Exception:
            pass

