    def _fetchWordplayListing(self, url: str) -> str:
        """Fetch a Wordplay listing page (home or category), using the text cache when enabled."""
        try:
            u = (url or "").strip()
        except Exception:
            u = url or ""
        if not u:
            u = WORDPLAY_HOME_URL
        if not re.match(r"(?i)^https?://", u):
            u = _absUrl("https://www.merriam-webster.com", u)

        cacheEnabled = bool(self._settings.get("cacheEnabled", True))
        ckey = "__wordplay__:" + u
        if cacheEnabled and ckey in self._cache:
            cached = self._cache.get(ckey) or {}
            try:
                htmlText = cached.get("html") or ""
                if htmlText:
                    return htmlText
            except Exception:
                pass

        htmlText = _httpGet(u)
        if cacheEnabled:
            try:
                self._cache[ckey] = {"html": htmlText, "fetchedAt": int(time.time())}
                _saveJson(_cachePath(), self._cache)
            except Exception:
                pass
        return htmlText

    def _fetchGrammarListing(self, url: str) -> str:
        """Fetch a Grammar & Usage listing page (home or category), using the text cache when enabled."""
        try:
            u = (url or "").strip()
        except Exception:
            u = url or ""
        if not u:
            u = GRAMMAR_HOME_URL
        if not re.match(r"(?i)^https?://", u):
            u = _absUrl("https://www.merriam-webster.com", u)

        cacheEnabled = bool(self._settings.get("cacheEnabled", True))
        ckey = "__grammar__:" + u
        if cacheEnabled and ckey in self._cache:
            cached = self._cache.get(ckey) or {}
            try:
                htmlText = cached.get("html") or ""
                if htmlText:
                    return htmlText
            except Exception:
                pass

        htmlText = _httpGet(u)
        if cacheEnabled:
            try:
                self._cache[ckey] = {"html": htmlText, "fetchedAt": int(time.time())}
                _saveJson(_cachePath(), self._cache)
            except Exception:
                pass
        return htmlText

    def _openWordplayArticle(self, url: str) -> None:
        """Fetch and display a Wordplay article in the main Results area."""
        try:
            raw = self._fetchWordplayListing(url)
        except Exception:
            log.exception("Wordplay: failed to fetch article")
            ui.message("Failed to load article.")
            return

        title, htmlDoc = _trimWordplayArticleHtml(raw)
        try:
            self._wordplayCurrentTitle = (title or '').strip()
        except Exception:
            self._wordplayCurrentTitle = (title or '')
        # Inject a visible 'Wordplay' marker line at the top of the rendered content.
        try:
            htmlDoc = re.sub(r"(?is)<body\b[^>]*>", lambda mm: mm.group(0) + "<p>Wordplay</p>\n", htmlDoc, 1)
        except Exception:
            pass
        # Show as normal results; don't alter lookup mode.
        try:
            self._currentIsSlang = False
            self._currentLastUpdatedLine = ""
        except Exception:
            pass
        # Ensure Results context menu has a URL for Copy URL / Open in browser.
        try:
            self._resultsKind = 'wordplay'
        except Exception:
            pass
        try:
            self._resultsPageUrl = (url or '').strip()
        except Exception:
            pass
        try:
            self._showResultInDialog(htmlDoc, "Wordplay: " + title)
            try:
                wx.CallLater(150, ui.message, "Results updated.")
            except Exception:
                pass
        except Exception:
            log.exception("Wordplay: failed to display article")
            ui.message("Failed to display article.")



    def _openGrammarArticle(self, url: str) -> None:
        """Fetch and display a Grammar & Usage article in the main Results area."""
        try:
            raw = self._fetchGrammarListing(url)
        except Exception:
            log.exception("Grammar: failed to fetch article")
            ui.message("Failed to load article.")
            return

        # Grammar & Usage articles use the same general MW article template family as Wordplay.
        # Reuse the conservative Wordplay article trimmer and final-pass cleanup.
        title, htmlDoc = _trimWordplayArticleHtml(raw)
        try:
            self._grammarCurrentTitle = (title or "").strip()
        except Exception:
            self._grammarCurrentTitle = (title or "")

        # Inject a visible marker line at the top of the rendered content.
        try:
            htmlDoc = re.sub(
                r"(?is)<body\b[^>]*>",
                lambda mm: mm.group(0) + "<p>Grammar &amp; Usage</p>\n",
                htmlDoc,
                1,
            )
        except Exception:
            pass

        # Ensure Results context menu has a URL for Copy URL / Open in browser.
        try:
            self._resultsKind = "grammar"
        except Exception:
            pass
        try:
            self._resultsPageUrl = (url or "").strip()
        except Exception:
            pass

        # Treat Grammar articles as (Article) for mode-dependent behaviors (e.g. disable Copy section).
        try:
            self._lastResultsMode = "article"
        except Exception:
            pass

        try:
            self._showResultInDialog(htmlDoc, "Grammar & Usage: " + (title or ""))
            try:
                wx.CallLater(150, ui.message, "Results updated.")
            except Exception:
                pass
        except Exception:
            log.exception("Grammar: failed to display article")
            ui.message("Failed to display article.")


    def onFavorites(self, evt):
        """Open the Favorites dialog."""
        try:
            # Defer opening to keep NVDA responsive.
            wx.CallAfter(self._openFavoritesDialog)
        except Exception:
            try:
                self._openFavoritesDialog()
            except Exception:
                pass

    def _openFavoritesDialog(self) -> None:
        # If keep-open is enabled, open Favorites modeless so the user can switch
        # focus back to Results after lookups.
        keepOpen = False
        try:
            keepOpen = bool(self._settings.get("keepFavoritesOpen", False))
        except Exception:
            keepOpen = False

        if keepOpen:
            try:
                dlg = getattr(self, "_favoritesDlg", None)
                if dlg and dlg:
                    try:
                        dlg.Raise()
                    except Exception:
                        pass
                    try:
                        dlg.listCtrl.SetFocus()
                    except Exception:
                        pass
                    return
            except Exception:
                pass

            try:
                dlg = FavoritesDialog(self)
                self._favoritesDlg = dlg
                try:
                    dlg.CentreOnParent()
                except Exception:
                    pass
                dlg.Show()
            except Exception:
                log.exception("mwLookup: failed to open Favorites dialog")
            return

        # Non keep-open mode: use a modal dialog (existing behavior).
        try:
            try:
                dlgExisting = getattr(self, "_favoritesDlg", None)
                if dlgExisting and dlgExisting:
                    try:
                        dlgExisting.Close()
                    except Exception:
                        pass
                    self._favoritesDlg = None
            except Exception:
                pass

            dlg = FavoritesDialog(self)
            dlg.ShowModal()
        except Exception:
            log.exception("mwLookup: failed to open Favorites dialog")
        finally:
            try:
                dlg.Destroy()
            except Exception:
                pass

    def _startWotd(self, url: str):
        if self._busy:
            ui.message("Please wait.")
            return
        self._busy = True
        try:
            self._setStatus("Loading Word of the Day…")
        except Exception:
            pass
        _WotdWorker(self, url).start()

    def _wotdNavigate(self, which: str):
        which = (which or "").strip().lower()
        u = ""
        if which == "prev":
            u = (self._wotdPrevUrl or "").strip()
        elif which == "next":
            u = (self._wotdNextUrl or "").strip()
        if not u:
            ui.message("No page available.")
            return
        self._startWotd(u)

    def _wotdOpenEntry(self):
        """Open the current Word of the Day entry as a normal dictionary lookup."""
        try:
            w = (getattr(self, "_wotdEntryWord", "") or "").strip()
        except Exception:
            w = ""
        if not w:
            ui.message("No entry available.")
            return
        try:
            self.startLookup(w, force=True)
        except Exception:
            try:
                self.startLookup(w)
            except Exception:
                ui.message("Unable to open entry.")

    def _onWotdStarted(self):
        try:
            ui.message("Loading Word of the Day…")
        except Exception:
            pass

    def _onWotdFinished(self, res: Optional[Dict[str, Any]], err: Optional[Exception]):
        self._busy = False
        if err or not res:
            if err:
                log.exception("mwLookup: Word of the Day failed", exc_info=err)
            try:
                self._setStatus("Error.")
            except Exception:
                pass
            ui.message("Unable to load Word of the Day. Please try again.")
            return

        try:
            html = res.get("html", "") or ""
            title = res.get("title", "Word of the Day") or "Word of the Day"
            self._wotdCurrentUrl = (res.get("currentUrl") or "").strip()
            self._resultsPageUrl = (self._wotdCurrentUrl or "").strip()
            self._wotdPrevUrl = (res.get("prevUrl") or "").strip()
            self._wotdNextUrl = (res.get("nextUrl") or "").strip()
            self._wotdIsRoot = bool(res.get("isRoot", True))
            self._wotdEntryWord = (res.get("wotdWord") or "").strip()
            if self._wotdIsRoot:
                self._wotdNextUrl = ""
            self._currentAudio = res.get("audio", []) or []
            # Word of the Day is not a dictionary lookup; do not set _currentQuery.
            # This ensures Browse Words opens the landing selector (A–Z/0-9/BIO/GEO).
            self._currentBrowseUrl = ""
            self._currentIsSlang = False
            self._currentLastUpdatedLine = ""
            self._currentQuery = ""
            self._setStatus("Done.")
            # Word of the Day is a non-entry view; suppress Results (Dictionary/Thesaurus) label.
            self._resultsKind = "wotd"
            try:
                self._updateResultsLabel()
            except Exception:
                pass
            self._setSuggestionsVisible(False)
            self.suggestions.Set([])
            self._showResultInDialog(html, title)
        except Exception:
            log.exception("mwLookup: Word of the Day render failed")
            ui.message("Unable to display Word of the Day.")

    def _fetchWordOfTheDay(self, url: str) -> Dict[str, Any]:
        """Fetch and build a displayable HTML document for Word of the Day."""
        curUrl = (url or "").strip() or WOTD_URL
        # Text caching for Word of the Day (respects Settings → Enable text caching).
        cacheEnabled = bool(self._settings.get("cacheEnabled", True))
        # Normalize: ensure absolute URL.
        try:
            if curUrl and not re.match(r"(?i)^https?://", curUrl):
                curUrl = _absUrl("https://www.merriam-webster.com", curUrl)
        except Exception:
            pass
        ckey = "__wotd__:" + curUrl
        if cacheEnabled and ckey in self._cache:
            cached = self._cache.get(ckey) or {}
            try:
                # Root (/word-of-the-day) changes daily; only trust same-day cache.
                if bool(cached.get("isRoot", False)):
                    if (cached.get("cacheDay") or "") == time.strftime('%Y-%m-%d', time.localtime()):
                        return cached
                else:
                    return cached
            except Exception:
                pass

        raw = _httpGet(curUrl)
        raw = _trimWotdHtml(raw)
        prevUrl, nextUrl = _extractWotdNavUrls(raw, "https://www.merriam-webster.com")
        # Treat only /word-of-the-day pages as navigable; fall back to root when given a non-WOTD URL.
        if "/word-of-the-day" not in curUrl.lower():
            curUrl = WOTD_URL
        isRoot = (curUrl.rstrip("/").lower() == WOTD_URL.rstrip("/").lower())
        showNext = (not isRoot)
        audioBtns, injected = _extractAudioButtons(raw)
        injected = _injectWotdNavLines(injected, prevUrl, nextUrl, showNext=showNext)
        idx = injected.lower().find("<h1")
        body = injected[idx:] if idx >= 0 else injected
        htmlDoc = "<html><body>" + body + "</body></html>"
        try:
            m = re.search(r"(?is)<h1\\b[^>]*>(.*?)</h1\\s*>", body)
            w = re.sub(r"<[^>]+>", " ", (m.group(1) if m else ""))
            w = re.sub(r"\s+", " ", w).strip()
            title = ("Word of the Day — " + w) if w else "Word of the Day"
        except Exception:
            title = "Word of the Day"
        res = {
            "type": "wotd",
            "title": title,
            "html": htmlDoc,
            "audio": audioBtns,
            "prevUrl": prevUrl,
            "nextUrl": nextUrl,
            "currentUrl": curUrl,
            "isRoot": isRoot,
            "wotdWord": w,
            "fetchedAt": int(time.time()),
            "cacheDay": time.strftime('%Y-%m-%d', time.localtime()) if isRoot else "",
        }
        if cacheEnabled:
            try:
                self._cache[ckey] = res
                _saveJson(_cachePath(), self._cache)
            except Exception:
                pass
        return res


    def onOpenSettings(self, evt):
        """Open Settings dialog and persist changes."""
        try:
            dlg = SettingsDialog(self, self._settings)
            # Wire destructive actions to the main dialog (they apply immediately).
            dlg.clearHistoryBtn.Bind(wx.EVT_BUTTON, lambda e: self.onClearHistory(e))
            dlg.clearTextCacheBtn.Bind(wx.EVT_BUTTON, lambda e: self.onClearTextCache(e))
            dlg.clearAudioCacheBtn.Bind(wx.EVT_BUTTON, lambda e: self.onClearAudioCache(e))
            ns = dlg.getSettings()
            try:
                dlg.Destroy()
            except Exception:
                pass
            if not ns:
                return
            self._settings = _mergeSettings(ns)
            # Persist.
            _saveJson(_settingsPath(), self._settings)
            # Apply runtime toggles.
            try:
                global _AGGRESSIVE_BOILERPLATE
                _AGGRESSIVE_BOILERPLATE = True
            except Exception:
                pass
            self._debugEnabled = bool(self._settings.get("debugEnabled", False))
            _setDebugEnabled(self._debugEnabled)
            self._applyHistoryUi()
            ui.message("Settings saved.")
        except Exception:
            log.exception("mwLookup: settings dialog failed")


    def _resetLookupState(self) -> None:
        """Reset per-session lookup state.

        The global plugin keeps this dialog instance alive (Hide/Veto close). When reopening,
        we should not treat stale results as an active lookup.
        """
        try:
            self._currentAudio = []
        except Exception:
            pass
        try:
            self._audioLineToUrl = {}
        except Exception:
            pass
        self._currentBrowseUrl = ""
        self._currentQuery = ""
        self._resultsPageUrl = ""
        self._currentIsSlang = False
        self._currentLastUpdatedLine = ""
        try:
            self._resultsKind = "empty"
        except Exception:
            pass
        try:
            self.searchCtrl.SetValue("")
        except Exception:
            pass
        try:
            self.resultsCtrl.SetValue("")
        except Exception:
            pass
        try:
            self._updateResultsLabel()
        except Exception:
            pass

    def _onClose(self, evt):
        try:
            self._unbindMwLocalInputGestures()
            try:
                _setActiveDialog(None)
            except Exception:
                pass
            try:
                self._resetLookupState()
            except Exception:
                pass
            self.Hide()
        finally:
            try:
                evt.Veto()
            except Exception:
                    pass

    def _onCancel(self, evt):
        """Handle wx.ID_CANCEL (e.g., Esc) for this modeless dialog."""
        try:
            self._unbindMwLocalInputGestures()
            try:
                self._resetLookupState()
            except Exception:
                pass
            self.Hide()
        except Exception:
            pass

    def _onCloseButton(self, evt):
        """Handle the Close button."""
        try:
            self._unbindMwLocalInputGestures()
            try:
                self._resetLookupState()
            except Exception:
                pass
            self.Hide()
        except Exception:
            pass

