    def _onAccelFocusHistory(self, evt):
        # Alt+H: move focus to History list (dialog-local only)
        try:
            # If NVDA Input Help (NVDA+1) is active, only announce.
            if getattr(self, '_inputHelpActive', None) and self._inputHelpActive():
                try: ui.message("Move focus to History.")
                except Exception: pass
                return
            self.history.SetFocus()
            # Ensure a usable selection (Enter works immediately).
            try:
                cnt = int(self.history.GetCount())
            except Exception:
                cnt = 0
            if cnt > 0:
                try:
                    sel = int(self.history.GetSelection())
                except Exception:
                    sel = -1
                if sel < 0:
                    try:
                        self.history.SetSelection(0)
                    except Exception:
                        pass
        except Exception:
            pass



