    def _sanitizeLookupSelection(self, s: str) -> str:
        """Sanitize a selection before sending it to Merriam-Webster.

        Some text selections in Results may include trailing sentence punctuation or quotes
        (e.g. Fido.”, foo:, bar...), which can break lookups and trigger suggestion pages.
        We only remove *trailing* junk, and keep internal punctuation intact.
        """
        try:
            import unicodedata
        except Exception:
            unicodedata = None  # type: ignore

        sel = (s or "").strip()
        if not sel:
            return ""

        # Drop trailing Unicode format chars (ZW*, bidi isolates, etc.).
        if unicodedata:
            try:
                while sel and unicodedata.category(sel[-1]) == "Cf":
                    sel = sel[:-1]
            except Exception:
                pass
        sel = sel.strip()

        # Repeatedly strip common trailing punctuation/quotes/closers.
        # Keep this conservative: only the *end* is affected.
        try:
            import re
            while True:
                before = sel
                # Remove trailing ellipsis ("..." or "…").
                sel = re.sub(r"(?:\.\.\.|…)+$", "", sel)
                # Remove trailing quotes and punctuation.
                sel = re.sub(r"[\"\u201c\u201d\u2018\u00ab\u00bb\u2039\u203a\:;\,\u060c\!\?\u061f\u06d4]+$", "", sel)
                # Remove trailing closers.
                sel = re.sub(r"[\)\]\}]+$", "", sel)
                sel = sel.strip()
                if sel == before:
                    break
        except Exception:
            pass

        # If the selection ends with a single sentence period (e.g. "Fido."),
        # remove it only when it's the *only* period in the string.
        try:
            if sel.endswith(".") and sel.count(".") == 1:
                sel = sel[:-1].rstrip()
        except Exception:
            pass

        return sel

    def _onLookupSelectionInResults(self):
        """Look up currently selected text inside resultsCtrl (results window only)."""
        try:
            sel = (self.resultsCtrl.GetStringSelection() or "").strip()
        except Exception:
            sel = ""
        try:
            sel = self._sanitizeLookupSelection(sel)
        except Exception:
            pass
        if not sel:
            try:
                ui.message("No selection.")
            except Exception:
                pass
            return
        try:
            ui.message(f"Searching Dictionary: {sel}")
        except Exception:
            pass
        # Reuse the normal search pipeline.
        try:
            self.setQuery(sel)
        except Exception:
            pass
        try:
            self.startLookup(sel, modeOverride="dictionary")
        except Exception:
            pass


