    def _mwJumpToHeading(self, prev: bool):
        """Jump to the next/previous cached heading in results.

        IMPORTANT: Navigation must be based on the cached *logical* heading offsets
        computed from the final rendered LF text (see _computeHeadingPositions).
        Line-based APIs (PositionToXY/PositionFromLine) are not reliable across wx
        builds and can cause H/Shift+H to get stuck on the first heading.
        """
        if not getattr(self, "_resultHeadings", None):
            try:
                ui.message("No headings in results.")
            except Exception:
                pass
            return

        # Work in logical offsets.
        try:
            val = self.resultsCtrl.GetValue() or ""
        except Exception:
            val = ""
        try:
            caret_native = int(self.resultsCtrl.GetInsertionPoint())
        except Exception:
            caret_native = 0
        try:
            caret = int(self._toLogicalPos(caret_native, val))
        except Exception:
            caret = int(caret_native)

        # Headings are tuples: (lineNo, headingText, posCharLogical).
        try:
            headings = sorted(self._resultHeadings, key=lambda x: int(x[2]))
        except Exception:
            headings = list(self._resultHeadings)

        target = None
        if prev:
            for _ln, ht, p in headings:
                try:
                    p = int(p)
                except Exception:
                    continue
                if p < caret:
                    target = (p, ht)
                else:
                    break
            if target is None:
                try:
                    ui.message("First heading.")
                except Exception:
                    pass
                return
        else:
            for _ln, ht, p in headings:
                try:
                    p = int(p)
                except Exception:
                    continue
                if p > caret:
                    target = (p, ht)
                    break
            if target is None:
                try:
                    ui.message("Last heading.")
                except Exception:
                    pass
                return

        pos_logical, headingText = target
        self._moveCaretToHeadingPos(int(pos_logical), headingText, nativePosAlready=False)


    def _mwGetAudioLineNos(self) -> list[int]:
        """Return a sorted list of 0-based line numbers for injected audio lines."""
        out: list[int] = []
        try:
            n = int(self.resultsCtrl.GetNumberOfLines())
        except Exception:
            try:
                n = (self.resultsCtrl.GetValue() or "").count("\n") + 1
            except Exception:
                n = 0
        for i in range(max(0, n)):
            try:
                ln = (self.resultsCtrl.GetLineText(int(i)) or "").strip()
            except Exception:
                ln = ""
            if _isAudioLine(ln):
                out.append(int(i))
        return out

