    def _mwGetListLineNos(self) -> list[int]:
        """Return a sorted list of 0-based line numbers for detected list starts in results."""
        try:
            out = [int(x) for x in (getattr(self, "_resultListLineNos", None) or [])]
            out = [x for x in out if x >= 0]
            out.sort()
            return out
        except Exception:
            return []

    def _detectListLineNosFromFinalText(self, resultsText: str) -> list[int]:
        """Detect list start lines from the *final* rendered results text.

        List-start line numbers produced during HTML->text conversion can become
        stale after later text-level repairs that insert/join/split lines. That
        staleness shows up as progressive drift (landing a few lines/items into
        each list).

        To avoid drift, we detect list blocks directly from the final rendered
        text that is actually placed into resultsCtrl.
        """
        try:
            lines = (resultsText or "").splitlines()
        except Exception:
            lines = []
        if not lines:
            return []

        try:
            listHeaderRe = re.compile(
                r"(?i)^(?:synonyms(?:\s*&\s*similar\s*words)?|antonyms(?:\s*&\s*near\s*antonyms)?|near\s*antonyms|related\s*words|words\s*related\s*to\b|synonym\s*discussion|examples?)\b"
            )
            asInRe = re.compile(r"(?i)^(?:\d+\s+)?as\s+in\b")
        except Exception:
            return []

        def _next_non_empty(idx: int) -> int:
            j = idx
            while j < len(lines) and not (lines[j] or "").strip():
                j += 1
            return j if j < len(lines) else -1

        out = []
        try:
            for i in range(len(lines)):
                cur = (lines[i] or "").strip()
                if not cur:
                    continue
                if not (listHeaderRe.match(cur) or asInRe.match(cur)):
                    continue
                j = _next_non_empty(i + 1)
                if j < 0:
                    continue
                nxt = (lines[j] or "").strip()
                if not nxt:
                    continue
                if nxt.lower().startswith("play audio pronunciation"):
                    continue
                out.append(int(j))
        except Exception:
            out = []

        try:
            out = sorted({int(x) for x in out if int(x) >= 0})
        except Exception:
            out = []
        return out

