    def _onCharHook(self, evt: wx.KeyEvent) -> None:
        """Local keyboard handling for the Example Sentences dialog."""
        try:
            key = evt.GetKeyCode()
            ctrl = evt.ControlDown()
            alt = evt.AltDown()
            if key == wx.WXK_ESCAPE and not alt and not ctrl:
                try:
                    self.Close()
                except Exception:
                    try:
                        self.Destroy()
                    except Exception:
                        pass
                return
        except Exception:
            pass
        evt.Skip()
